#include <print>
#include <vector>

int main() {
    std::vector<int> v = {3, 1, 4, 1, 5};
    std::vector<int> pre(v.size() + 1, 0);            // pre[0] = 0 当地基
    std::vector<long long> pre64(v.size() + 1, 0);
    for (int i = 0; i < static_cast<int>(v.size()); ++i) {
        pre[i + 1] = pre[i] + v[i];
        pre64[i + 1] = pre64[i] + v[i];
        std::print("填完 pre[{}]={:2}  此刻整个 pre：", i + 1, pre[i + 1]);
        for (int k = 0; k <= static_cast<int>(v.size()); ++k) std::print("{} ", pre[k]);
        std::println("");
    }
    std::println("第 2~4 个的和 = {}", pre[4] - pre[1]);
    return 0;
}
// 一行行看下去：0 3 4 8 0 0 到 0 3 4 8 9 14，表是从地基往右一格一格推出来的

