int main() {
    std::vector<int> v = {3, 1, 4, 1, 5};
    std::vector<int> pre(v.size() + 1, 0);
    for (int i = 0; i < static_cast<int>(v.size()); ++i)
        pre[i + 1] = pre[i] + v[i];
    std::println("到第 3 个为止共 {}", pre[3]);
    std::println("第 2~4 个的和 = {}", pre[4] - pre[1]);
    return 0;
}
